import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int minLen = in.nextInt();
        int minTypes = in.nextInt();
        while (in.hasNext()) {
            String user = in.next();
            String pwd = in.next();
            int lower = 0;
            int upper = 0;
            int digit = 0;
            int other = 0;
            for (int i = 0; i < pwd.length(); i++) {
                char c = pwd.charAt(i);
                if (c >= 'a' && c <= 'z') {
                    lower = 1;
                } else if (c >= 'A' && c <= 'Z') {
                    upper = 1;
                } else if (c >= '0' && c <= '9') {
                    digit = 1;
                } else {
                    other = 1;
                }
            }
            int classes = lower + upper + digit + other;
            boolean ok = pwd.length() >= minLen && classes >= minTypes && !pwd.contains(user);
            System.out.println(user + ": " + (ok ? "ACCEPT" : "REJECT"));
        }
    }
}

