#include <iostream>
#include <string>
using namespace std;

int main() {
    int minLen, minTypes;
    cin >> minLen >> minTypes;
    string user, pwd;
    while (cin >> user >> pwd) {
        int lower = 0;
        int upper = 0;
        int digit = 0;
        int other = 0;
        for (char c : pwd) {
            if (c >= 'a' && c <= 'z') {
                lower = 1;
            } else if (c >= 'A' && c <= 'Z') {
                upper = 1;
            } else if (c >= '0' && c <= '9') {
                digit = 1;
            } else {
                other = 1;
            }
        }
        int classes = lower + upper + digit + other;
        bool ok = (int) pwd.size() >= minLen && classes >= minTypes && pwd.find(user) == string::npos;
        cout << user << ": " << (ok ? "ACCEPT" : "REJECT") << endl;
    }
    return 0;
}
